mapper.select:
SELECT id, blog_id FROM tb_blog_comments
WHERE id = #{replyId} AND user_id = #{userId}
  AND parent_id > 0 AND answer_id = parent_id AND status IN (0, 3)

mapper.update:
UPDATE tb_blog_comments SET status = 3
WHERE id = #{replyId} AND blog_id = #{blogId} AND user_id = #{userId}
  AND parent_id > 0 AND answer_id = parent_id AND status = 0

UPDATE tb_blog
SET comments = CASE WHEN COALESCE(comments, 0) > 0 THEN comments - 1 ELSE 0 END
WHERE id = #{blogId}

mapper.select:
SELECT id, blog_id FROM tb_blog_comments
WHERE id = #{commentId} AND user_id = #{userId}
  AND parent_id = 0 AND answer_id = 0 AND status IN (0, 3)

mapper.update:
UPDATE tb_blog_comments SET status = 3
WHERE id = #{commentId} AND blog_id = #{blogId} AND user_id = #{userId}
  AND parent_id = 0 AND answer_id = 0 AND status = 0

mapper.select:
SELECT id, blog_id, user_id, content, create_time FROM tb_blog_comments
WHERE blog_id = #{blogId} AND parent_id = #{commentId} AND answer_id = #{commentId} AND status = 0
AND id < #{beforeId}
ORDER BY id DESC LIMIT #{limit}

